const aceitos = [
  "Ok",
  "Bom",
  "Temperatura dentro da faixa normal",
  "Sem fumaça anormal",
  "VTR Limpa",
  "Dentro da Validade",
  "Normal",
  "Cheio",
  "Acima da metade",
  "Sem Vazamento",
  "Não tem ruídos",
  "Alto",
  "Presente"
];

const camposVerificar = [
  "NÍVEL DO ÓLEO DO MOTOR ",
  "VALIDADE DO ÓLEO DO MOTOR",
  "NÍVEL DE ÓLEO DO HIDRÁULICO ",
  "NÍVEL DE FLUIDOS DE FREIO",
  "NIVEL E ESTADO ÁGUA DO RADIADOR ",
  "NIVEL DE COMBUSTÍVEL",
  "POSSÍVEIS VAZAMENTOS ",
  "RUIDOS ANORMAIS ",
  "AR CONDICIONADO LIMPEZA E MANUTENÇÃO",
  "MARCADOR DE TEMPERATURA DO MOTOR ",
  "PRESENÇA DE FUMAÇA ANORMAL DE SISTEMA DE ESCAPAMENTO ",
  "TRIANGULO DE SINALIZAÇÃO , CHAVE DE RODA E MACACO",
  "CALIBRAGEM E ESTADO DOS PENUS E ESTEPE",
  "ARRANHÕES E AMASSADOS NA CARROCERIA E CABINE DO VEÍCULO",
  "FUNCIONAMENTO DO LIMPADOR DE PARA - BRISAS E ESGUICHO",
  "LIMPEZA GERAL EXTERNA E INTERNA DA AMBULÂNCIA OBRIGATÓRIA",
  "EXTINTOR ",
  "CHAVE  TROCA DE OXIGENIO",
  "VERIFICAR DESGASTES DAS PASTILHAS E DISCO DE FREIO",
  "VERIFICAR O ESTADO DOS AMORTECEDORES",
  "VALIDADE DO ÓLEO DO MOTOR "
];

const vtr = $input.first().json.VTRS;

// adiciona o campo apenas se for uma das VTRs específicas
if (["USA 10", "USA 11", "USB 10", "USB 11"].includes(vtr)) {
  camposVerificar.push("NIVEL DE ADBLUE ( VTR 10 E VTR 11)");
}

return items.map(item => {
  const data = item.json;

  const foraDoPadrao = camposVerificar.filter(campo => {
    const valor = data[campo];
    // converte para string e remove espaços, se não for nulo/undefined
    const valorStr = valor !== undefined && valor !== null ? String(valor).trim() : "";
    return valorStr && !aceitos.includes(valorStr);
  });

  return {
    json: {
      ...data,
      resultado: foraDoPadrao.length === 0 ? "Aprovado" : "Reprovado",
      campos_fora_do_padrao: foraDoPadrao
    }
  };
});

const resultado = items.map(item => {
  const dados = item.json;
  const campos = dados.campos_fora_do_padrao || [];

  const foraDoPadrao = campos.map(campo => ({
    campo,
    valor: dados[campo] !== undefined && dados[campo] !== "" ? dados[campo] : "Não informado"
  }));

  return {
    json: {
      VTR: dados.VTRS,
      condutor: dados["CONDUTOR RESPONSÁVEL"].trim(),
      fora_do_padrao: foraDoPadrao,
      pendencias: dados["PENDÊNCIAS/OBSERVAÇÕES"] || ""
    }
  };
});

return resultado;

const aceitos = [
  "SIM",
  "Acima de 100 libras",
  "Acima de 50 libras",
  "Todos PRESENTES",
  "LACRADO"
];

const camposVerificar = [
  "LIXEIRA 1 + SACO INFECTANTE 10 + SACO COMUM 10",
  "APARADEIRA 1 + PAPAGAIO 1 + CUBA",
  "KIT SUTURA 1 + KIT PARTO 1",
  "ASPIRADOR PORTÁTIL 1 + NEBULIZADOR PORTÁTIL 01",
  "01 KIT SSVV (GLICOSÍMETRO 1 + ESTETOSCÓPIO ADULTO E INFANTIL 1 + TERMÔMETRO 1 + TENSIÔMETRO MANUAL E DIGITAL 1)",
  "OXIGÊNIO GRANDE 01 (LITRAGEM CILINDRO DE DOIS METROS) + MANÔMETRO",
  "OXIGÊNIO GRANDE 02 (LITRAGEM CILINDRO DE DOIS METROS) + MANÔMETRO",
  "OXIGÊNIO PORTÁTIL (LITRAGEM CILINDRO DE TRANSPORTE) + MANÔMETRO",
  "FLUXÔMETRO 2 + BICO DE SAÍDA FLUXOMETRO 2 + ASPIRADOR DA RÉGUA 1",
  "FICHAS DE QRU (HAPVIDA, BEM CUIDAR E UNIMED AEROMÉDICO) + CANETA 1",
  "DECLARAÇÃO DE ÓBITO (1 UNIDADE)",
  "JELCOS 2 (24 + 22 + 20 + 18 + 16)",
  "SCALP 2 (25 + 23 + 21)",
  "TIRA DE GLICEMIA 10 + LANCETA 10",
  "AGULHAS 5 (25X7 + 25X8 + 40X12) + TRANSOFIX 2 + POLIFIX 3",
  "SERINGAS 2 (1ML + 3ML) + 3 (5ML + 10ML + 20ML) + 1 (60ML)",
  "ESPARADRAPO 1 + EQUIPO MACROGOTAS 3 + TESOURA 1 + LANTERNA 1 + EQUIPO MICROGOTAS 1",
  "LONA DE TRANSPORTE 1 + MANTA TÉRMICA 1",
  "COLETOR DE SISTEMA FECHADO 1 + SVD (Nº18 E 16) 2 + SVA (Nº12) 2 + D.U 2 + SNG (Nº12) 1 + SNE (Nº12) 1 + COLETOR DE SISTEMA ABERTO 1 + LIDOCAÍNA 1 + CLOREXIDINA AQUOSA 1",
  "S.F 0,9% 500ML 2 + S.G 5% 500ML 1 + RINGER LACTATO 500ML 2 + S.G 5% 250ML 2 + S.F 0,9% 100ML 3",
  "ÁGUA DESTILADA 10ML 10 + GLICOSE 50% 10ML 10 + S.F 0,9% 10ML 10",
  "PACOTE DE GAZE 6 + COMPRESSAS 2 + ATADURAS 6",
  "MÁSCARAS 10 + LENÇÓIS DESCARTÁVEIS 10 + TOUCA 10 + LENÇOL AZUL 5",
  "CAIXA DE LUVA (P 1 - M 1 - G 1)",
  "LUVA ESTÉRIL (7,0 1 + 7,5 1 + 8,0 1)",
  "DISPENSER ÁLCOOL GEL 1 + ALMOTOLIA ÁLCOOL 70% 1",
  "CAPA DE CHUVA 4",
  "KIT COVID 4 + ÓCULOS DE PROTEÇÃO 4",
  "M.R ADULTO 2 + INFANTIL 2 + KIT MACRONEBULIZAÇÃO 1 + LÁTEX 2 + UMIDIFICADOR 2 + M.N ADULTO 1 E INFANTIL 1",
  "CN ADULTO 2 + CN INFANTIL 2",
  "SONDAS DE ASPIRAÇÃO TRAQUEAL (Nº6 2 + Nº8 2 + Nº10 2 + Nº12 2 + Nº14 2)",
  "MOCHILA DE MEDICAÇÕES COM LACRE",
  "MOCHILA VIA AÉREA",
  "MOCHILA DE TRAUMA",
  "CABO DE FORÇA",
  "CABOS DE MONITORIZAÇÃO CARDÍACA + ELETRODOS (ADUL E PED) + OXIMETRIA DE PULSO (ADULTO/PED/NEO) + CABO DE PNI (ADULTO/PED/NEO) + MANGUEIRA VENTILADOR + VÁLVULA DE PRESSÃO",
  "CARDIOVERSOR 1",
  "VENTILADOR DE TRANSPORTE COM FONTE 1",
  "CIRCUITO VENTILADOR ADULTO 1 + PED 1 + NEO 1",
  "BOMBA DE INFUSÃO COM FONTE 3",
  "EQUIPO BOMBA PADRÃO E FOTO 3",
  "LIMPEZA CONCORRENTE (EQUIPAMENTOS E BANCADAS)",
];

const DEBUG = false; // se quiser ver logs, coloca true

// normaliza chaves/valores: remove zero-width, remove acentos, substitui qualquer sequência de não-alfanum por espaço, colapsa espaços e uppercase
const normalizeKey = str => {
  if (str === undefined || str === null) return "";
  let s = String(str);
  // remove zero-width and BOM
  s = s.replace(/[\u200B-\u200D\uFEFF]/g, "");
  // separa acentos (NFD) e remove marcas de acento
  if (s.normalize) s = s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  // substitui qualquer sequência não alfanumérica por espaço
  s = s.replace(/[^A-Za-z0-9]+/g, " ");
  // colapsa espaços e uppercase
  return s.trim().replace(/\s+/g, " ").toUpperCase();
};

const aceitosNorm = aceitos.map(normalizeKey);

return items.map(item => {
  const data = item.json;

  if (DEBUG) console.log("---- novo item ----");

  const foraDoPadrao = [];

  for (const campo of camposVerificar) {
    const campoNorm = normalizeKey(campo);

    // procura a chave correspondente no JSON (comparando chaves normalizadas)
    let entradaEncontrada = null;
    for (const [chave, valor] of Object.entries(data)) {
      if (normalizeKey(chave) === campoNorm) {
        entradaEncontrada = { chave, valor };
        break;
      }
    }

    const valorStr = entradaEncontrada && entradaEncontrada.valor !== undefined && entradaEncontrada.valor !== null
      ? String(entradaEncontrada.valor).trim()
      : "";

    const valorNorm = normalizeKey(valorStr);

    // se houver valor e não for um valor aceito → fora do padrão
    if (valorStr && !aceitosNorm.includes(valorNorm)) {
      foraDoPadrao.push(campo);
      if (DEBUG) console.log("Fora do padrão:", campo, "->", entradaEncontrada.chave, "=", valorStr);
    } else if (DEBUG) {
      if (entradaEncontrada) {
        console.log("OK:", campo, "->", entradaEncontrada.chave, "=", valorStr || "(vazio)");
      } else {
        console.log("Não encontrado no JSON:", campo);
      }
    }
  }

  return {
    json: {
      ...data,
      resultado: foraDoPadrao.length === 0 ? "Aprovado" : "Reprovado",
      campos_fora_do_padrao: foraDoPadrao
    }
  };
});

const resultado = items.map(item => {
  const dados = item.json;
  const campos = dados.campos_fora_do_padrao || [];

  const foraDoPadrao = campos.map(campo => ({
    campo,
    valor: dados[campo] !== undefined && dados[campo] !== "" ? dados[campo] : "Não informado"
  }));

  return {
    json: {
      VTR: dados.VTR,
      enfermeiro: dados["ENFERMEIRO RESPONSÁVEL PELA CONFERÊNCIA/COREN"].trim(),
      fora_do_padrao: foraDoPadrao,
      pendencias: dados["PENDENCIAS"] || ""
    }
  };
});

return resultado;

// 🔹 Combina todos os arrays de items.json em um único array
const vtrs = items.flatMap(item => item.json);

// 🔹 Função para extrair o número da VTR
function getNumero(vtr) {
  if (!vtr || typeof vtr !== "string") return null;
  const match = vtr.match(/\d+/);
  return match ? parseInt(match[0], 10) : null;
}

// 🔹 Agrupar por número
const grupos = {};

vtrs.forEach(item => {
  if (!item.VTR) return;
  const numero = getNumero(item.VTR);
  if (!numero) return;

  if (!grupos[numero]) {
    grupos[numero] = {
      numero,
      VTRs: [],
      condutores: [],
      enfermeiros: [],
      pendencias_vtr: [],
      pendencias_usa_usb: [],
      fora_do_padrao_vtr: [],
      fora_do_padrao_usa_usb: [],
    };
  }

  grupos[numero].VTRs.push(item.VTR);

  // Condutores e enfermeiros
  if (item.condutor) grupos[numero].condutores.push(item.condutor);
  if (item.enfermeiro) grupos[numero].enfermeiros.push(item.enfermeiro);

  // Pendências
  if (item.pendencias && item.pendencias.length > 0) {
    if (item.condutor) {
      // Se tem condutor, é VTR → pendencias_vtr
      grupos[numero].pendencias_vtr.push(...[].concat(item.pendencias));
    } else if (item.enfermeiro) {
      // Se tem enfermeiro, é USA/USB → pendencias_usa_usb
      grupos[numero].pendencias_usa_usb.push(...[].concat(item.pendencias));
    }
  }

  // 🔁 Fora do padrão (mantém a inversão)
  if (item.fora_do_padrao && item.fora_do_padrao.length > 0) {
    if (item.VTR.startsWith("VTR")) {
      // Pertence à USA/USB
      item.fora_do_padrao.forEach(fp => {
        grupos[numero].fora_do_padrao_usa_usb.push({
          ...fp,
          origem: "USA/USB",
        });
      });
    } else if (item.VTR.startsWith("USA") || item.VTR.startsWith("USB")) {
      // Pertence à VTR
      item.fora_do_padrao.forEach(fp => {
        grupos[numero].fora_do_padrao_vtr.push({
          ...fp,
          origem: "VTR",
        });
      });
    }
  }
});

// 🔹 Verifica se está incompleto
const resultado = Object.values(grupos).map(grp => {
  const hasUSA = grp.VTRs.some(v => v.startsWith("USA") || v.startsWith("USB"));
  const hasVTR = grp.VTRs.some(v => v.startsWith("VTR"));
  grp.incompleto = !(hasUSA && hasVTR);
  return grp;
});

// 🔹 Verifica se há mais de um VTR ou mais de um USA/USB no mesmo grupo
resultado.forEach(grp => {
  const vtrsCount = grp.VTRs.filter(v => v.startsWith("VTR")).length;
  const usaUsbCount = grp.VTRs.filter(v => v.startsWith("USA") || v.startsWith("USB")).length;

  // Esperado: 1 VTR e 1 USA/USB
  grp.possui_excesso = (vtrsCount > 1 || usaUsbCount > 1);

  // Detalha o tipo de excesso
  grp.excesso_tipo = null;
  if (vtrsCount > 1 && usaUsbCount > 1) grp.excesso_tipo = "Múltiplos VTRs e múltiplos USA/USB";
  else if (vtrsCount > 1) grp.excesso_tipo = "Mais de um checklist USA/USB";
  else if (usaUsbCount > 1) grp.excesso_tipo = "Mais de um checklist VTR";
});

// 🔹 Retorna para o n8n
return resultado.map(r => ({ json: r }));

// 🔹 Função que normaliza nomes para o padrão "VTR"
const formatarVTRs = (lista) => {
  return lista.map(nome => nome.replace(/^(VTR|USA|USB)/i, "").trim());
};

// Entrada: items já vem com o array de VTRs combinadas
const vtrsArray = items.flatMap(item => item.json).filter(v => Object.keys(v).length > 0);

// 🔹 Caso o array venha vazio
if (vtrsArray.length === 0) {
  return [
    {
      json: {
        mensagens: ["Nenhum checklist foi preenchido até agora."],
        mensagemFinal: "🚨*Atenção🚨:*\\n\\nNenhum checklist foi preenchido até agora."
      }
    }
  ];
}

// 🔹 Detectar preenchimentos duplicados
const contadorVTR = {};
const contadorUSA = {};

vtrsArray.forEach(vtr => {
  const nomes = vtr.VTRs || [];
  nomes.forEach(n => {
    if (/^VTR/i.test(n)) {
      contadorVTR[n] = (contadorVTR[n] || 0) + 1;
    } else if (/^(USA|USB)/i.test(n)) {
      contadorUSA[n] = (contadorUSA[n] || 0) + 1;
    }
  });
});

// 🔹 Verifica se houve duplicação de VTR ou USA/USB
const vtrDuplicada = Object.values(contadorVTR).some(v => v > 1);
const usaDuplicada = Object.values(contadorUSA).some(v => v > 1);

// 🔹 Coletar apenas as VTRs que realmente preencheram algum checklist
const vtrUnicas = [
  ...new Set(
    vtrsArray
      .filter(v => {
        const hasCondutor = v.condutores && v.condutores.length > 0;
        const hasEnfermeiro = v.enfermeiros && v.enfermeiros.length > 0;
        return hasCondutor || hasEnfermeiro;
      })
      .flatMap(v => formatarVTRs(v.VTRs || []))
  )
];

const totalPreenchidas = vtrUnicas.length;

// 🔹 Gera mensagens individuais (sem repetir alerta de duplicado)
const mensagens = vtrsArray.map(vtr => {
  const vtrNomes = [...new Set(formatarVTRs(vtr.VTRs))];
  let msg = `🚑 *VTR:* ${vtrNomes.join(", VTR ")}`;

  const hasEnfermeiro = vtr.enfermeiros && vtr.enfermeiros.length > 0;
  const hasCondutor = vtr.condutores && vtr.condutores.length > 0;

  //
  // 🔹 Bloco VTR
  //
  msg += `\\n\\n🛠️ *Checklist VTR${hasCondutor ? ` (Condutor: ${vtr.condutores.join(", ")})` : ""}*`;

  if (!hasCondutor) {
    msg += `\\n⚠️ Não respondido`;
  } else {
    const foraVTR = vtr.fora_do_padrao_vtr || [];
    if (foraVTR.length > 0) {
      msg += `\\n🔎 ${foraVTR.length} item(s) fora do padrão:`;
      msg += foraVTR.map(f => `\\n• ${f.campo}: ${f.valor}`).join("");
    } else {
      msg += `\\n✅ Dentro do padrão`;
    }

    if (vtr.pendencias_vtr && vtr.pendencias_vtr.length > 0) {
      const limpas = vtr.pendencias_vtr.map(p => p.replace(/\n/g, " ").trim());
      msg += `\\n📌 Observações: ${limpas.join(", ")}`;
    }
  }

  //
  // 🔹 Bloco USA/USB
  //
  msg += `\\n\\n🏥 *Checklist USA/USB${hasEnfermeiro ? ` (Enfermeiro(a): ${vtr.enfermeiros.join(", ")})` : ""}*`;

  if (!hasEnfermeiro) {
    msg += `\\n⚠️ Não respondido`;
  } else {
    const foraUSA = vtr.fora_do_padrao_usa_usb || [];
    if (foraUSA.length > 0) {
      msg += `\\n🔎 ${foraUSA.length} item(s) fora do padrão:`;
      msg += foraUSA.map(f => `\\n• ${f.campo}: ${f.valor}`).join("");
    } else {
      msg += `\\n✅ Dentro do padrão`;
    }

    if (vtr.pendencias_usa_usb && vtr.pendencias_usa_usb.length > 0) {
      const limpas = vtr.pendencias_usa_usb.map(p => p.replace(/\n/g, " ").trim());
      msg += `\\n📌 Observações: ${limpas.join(", ")}`;
    }
  }

  return msg.trim();
});

// 🔹 Caso nenhuma VTR tenha realmente preenchido
if (totalPreenchidas === 0) {
  return [
    {
      json: {
        mensagens: ["Nenhum checklist foi preenchido até agora."],
        mensagemFinal: "*🚨Atenção🚨:*\\n\\nNenhum checklist foi preenchido até agora."
      }
    }
  ];
}

// 🔹 Cabeçalho com concordância verbal e plural correta
let cabecalho = "";
if (totalPreenchidas === 1) {
  cabecalho = `📋 *Apenas 1 VTR preencheu o checklist.*\\n\\n`;
} else {
  cabecalho = `📋 *${totalPreenchidas} VTRs preencheram o checklist.*\\n\\n`;
}

// 🔹 Monta alertas gerais de duplicação (só uma vez)
let alertas = "";
if (vtrDuplicada) alertas += "\\n🚨 *Alerta:* VTR preenchida duas vezes!";
if (usaDuplicada) alertas += "\\n🚨 *Alerta:* USA/USB preenchido duas vezes!";

// 🔹 Mensagem final completa
const mensagemFinal = cabecalho + mensagens.join("\\n\\n---\\n\\n") + (alertas ? `\\n\\n${alertas}` : "");

return [
  {
    json: {
      mensagens,
      mensagemFinal
    }
  }
];

const aceitos = [
  "SIM"
];

const camposVerificar = [
  "APARELHO AEROSOL",
  "APARADEIRA",
  "PAPAGAIO",
  "CAPA DE CHUVA",
  "CABO DE FORÇA",
