  "JELCO 16/18/20/22/24. 2 und",
  "POLIFIX. 3 und",
  "GARROTE",
  "EQUIPO MACROGOTAS. 3 und",
  "EQUIPO MICROGOTAS. 1 und",
  "LONA DE TRANSPORTE",
