  "S.F 0,9% 500ML. 2 und",
  "S.F 0,9% 250ML",
  "RINGER LACTATO 500ML. 2 und",
  "SORO GLICOSADO 5% 500ML. 1 und",
  "SORO GLICOSADO 5% 250ML",
  "ÁGUA DESTILADA 10 ML. 10 und",
  "GLICOSE 50% 10ML. 10 und",
  "PACOTE DE GAZE. 6 und",
  "COMPRESSA CIRÚRGICA LIMPEZA. 10 und",
  "ALMOTOLIA ÁLCOOL 70%",
  "CATETER TIPO ÓCULOS INFANTIL",
  "CATETER TIPO ÓCULOS ADULTO",
