// 🔹 Função auxiliar para limpar aspas de qualquer string
const limparTexto = (texto) => String(texto || "").replace(/"/g, "'").trim();

// 🔹 Detectar preenchimentos duplicados
const contadorVTR = {};
const contadorUSA = {};

vtrsArray.forEach(vtr => {
  const nomes = vtr.VTRs || [];
  nomes.forEach(n => {
    if (/^VTR/i.test(n)) {
      contadorVTR[n] = (contadorVTR[n] || 0) + 1;
    } else if (/^(USA|USB)/i.test(n)) {
      contadorUSA[n] = (contadorUSA[n] || 0) + 1;
    }
  });
});

