        const hasCondutor = v.condutores && v.condutores.length > 0;
        const hasEnfermeiro = v.enfermeiros && v.enfermeiros.length > 0;
        return hasCondutor || hasEnfermeiro;
      })
      .flatMap(v => formatarVTRs(v.VTRs || []))
  )
];

const totalPreenchidas = vtrUnicas.length;

// 🔹 Gera mensagens individuais
const mensagens = vtrsArray.map(vtr => {
  const vtrNomes = [...new Set(formatarVTRs(vtr.VTRs))];
  let msg = `🚑 *VTR:* ${vtrNomes.join(", VTR ")}`;

  const hasEnfermeiro = vtr.enfermeiros && vtr.enfermeiros.length > 0;
