// 🔹 Função para extrair o número da VTR
function getNumero(vtr) {
  if (!vtr || typeof vtr !== "string") return null;
  const match = vtr.match(/\d+/);
  return match ? parseInt(match[0], 10) : null;
}

// 🔹 Agrupar por número
const grupos = {};

vtrs.forEach(item => {
  if (!item.VTR) return;
  const numero = getNumero(item.VTR);
  if (!numero) return;

  if (!grupos[numero]) {
    grupos[numero] = {
      numero,
      VTRs: [],
      condutores: [],
      enfermeiros: [],
      pendencias_vtr: [],
      pendencias_usa_usb: [],
      fora_do_padrao_vtr: [],
      fora_do_padrao_usa_usb: [],
    };
  }

  grupos[numero].VTRs.push(item.VTR);

  // Condutores e enfermeiros
  if (item.condutor) grupos[numero].condutores.push(item.condutor);
  if (item.enfermeiro) grupos[numero].enfermeiros.push(item.enfermeiro);
