  if (item.pendencias && item.pendencias.length > 0) {
  if (item.condutor) {
    // Se tem condutor, é VTR → pendencias_vtr
    grupos[numero].pendencias_vtr.push(...[].concat(item.pendencias));
  } else if (item.enfermeiro) {
    // Se tem enfermeiro, é USA/USB → pendencias_usa_usb
    grupos[numero].pendencias_usa_usb.push(...[].concat(item.pendencias));
