// Normaliza texto para comparação: remove acentos, trim, múltiplos espaços, uppercase
function normalize(str) {
  if (str === undefined || str === null) return "";
  return String(str)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();
}

// Formata data ISO -> dd/mm/yyyy hh:mm:ss no timezone America/Fortaleza
function formatDateToFortaleza(iso) {
  if (!iso) return iso;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  const s = d.toLocaleString('pt-BR', {
    timeZone: 'America/Fortaleza',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });
  return s.replace(',', '');
}

