    const valStr = rawVal !== undefined && rawVal !== null ? String(rawVal).trim() : "";
    if (!valStr) return; // vazio - ignorar
    // se não pertence aos aceitos, adiciona ao objeto com o valor original
    if (!aceitosNorm.has(normalize(valStr))) {
      campos_fora_do_padrao[actualKey] = valStr;
