  if (Array.isArray(camposObj)) {
    return camposObj.map(campo => ({
      campo,
      valor: (dados && (dados[campo] !== undefined && dados[campo] !== "")) ? dados[campo] : "Não informado"
    }));
  }

  // Se veio como objeto mapeando campo -> valor: { "CAMPO A": "valor A", ... }
  if (typeof camposObj === 'object') {
    return Object.entries(camposObj).map(([campo, valor]) => ({
      campo,
      valor: (valor !== undefined && String(valor).trim() !== "")
        ? valor
        : (dados && (dados[campo] !== undefined && dados[campo] !== "") ? dados[campo] : "Não informado")
